B.TN=new A.o_("try {\n  const inputData = JSON.parse(ShortcutInput);\n  function findEl(doc, id) { return doc.getElementById(id) || doc.querySelector('[id$=\"' + id + '\"]') || doc.querySelector('[name$=\"' + id + '\"]') || doc.querySelector('[id=\"' + id.toLowerCase() + '\"]'); }\n  function getTargetEl(id) {\n    var el = findEl(document, id); if (el) return el;\n    var iframes = document.querySelectorAll('iframe');\n    for (var i = 0; i < iframes.length; i++) { try { if (iframes[i].contentDocument) { el = findEl(iframes[i].contentDocument, id); if (el) return el; } } catch (e) {} }\n    return null;\n  }\n  function setVal(id, val) {\n    var el = getTargetEl(id);\n    if (el) { el.value = val; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); el.style.backgroundColor = '#e8f5e9'; }\n  }\n  function setDrop(ids, text) {\n    if (!text) return;\n    var idList = Array.isArray(ids) ? ids : [ids];\n    var el = null;\n    for (var i = 0; i < idList.length; i++) { el = getTargetEl(idList[i]); if (el) break; }\n    if (el) {\n      var target = text.trim().toLowerCase();\n      var found = false;\n      for (var i = 0; i < el.options.length; i++) {\n        if (el.options[i].text.trim().toLowerCase() === target) {\n          el.selectedIndex = i; el.dispatchEvent(new Event('change', { bubbles: true }));\n          el.style.backgroundColor = '#e8f5e9'; found = true; break;\n        }\n      }\n      if (!found) {\n        for (var i = 0; i < el.options.length; i++) {\n          var optText = el.options[i].text.toLowerCase().trim();\n          if (optText.includes(target) || target.includes(optText)) {\n            el.selectedIndex = i; el.dispatchEvent(new Event('change', { bubbles: true }));\n            el.style.backgroundColor = '#e8f5e9'; found = true; break;\n          }\n        }\n      }\n    }\n  }\n  async function setFiles(id, photos) {\n    if (!photos || photos.length === 0) return;\n    var el = getTargetEl(id); if (!el) return;\n    var dt = new DataTransfer();\n    if (el.files && el.files.length > 0) { for (var i = 0; i < el.files.length; i++) { dt.items.add(el.files[i]); } }\n    for (var p of photos) {\n      try { var resp = await fetch('data:' + p.type + ';base64,' + p.data); var blob = await resp.blob(); dt.items.add(new File([blob], p.name, {type: p.type})); } catch(e) {}\n    }\n    el.files = dt.files; el.dispatchEvent(new Event('change', { bubbles: true }));\n    var yesRadio = getTargetEl('RBLPictures_0'); if (yesRadio) yesRadio.click();\n  }\n\n  if (inputData.type === 'photos') {\n    await setFiles('FUUploadFile', inputData.photos);\n  } else {\n    var lid = getTargetEl('LID');\n    if (lid && lid.innerText.trim()) {\n      completion(lid.innerText.trim()); return;\n    }\n    var partnerRadio = getTargetEl('RBLReportType_1') || document.querySelector('input[value=\"Partner\"]');\n    if (partnerRadio) partnerRadio.click();\n    setVal('TBWaterBodyName', inputData.waterbody);\n    setDrop(['DDLWaterbody', 'DDLWaterBody', 'waterbody', 'main_DDLWaterbody'], inputData.waterbody);\n    setVal('TBLatitude', inputData.lat);\n    setVal('TBLongitude', inputData.long);\n    setVal('TBLandmark', inputData.locationName);\n    setDrop(['LBCounty', 'DDLCounty', 'county', 'main_DDLCounty'], inputData.county);\n    setDrop(['DDLRegionalBoard', 'RegionalBoard', 'region', 'main_DDLRegionalBoard'], inputData.waterboardRegion);\n    setVal('TBName', inputData.personnel);\n    setVal('TBOrganization', inputData.program);\n    setVal('TBEmail', inputData.email);\n    setVal('TBDate', inputData.date);\n    setDrop(['DDLWeather', 'weather'], inputData.weather);\n    setDrop(['DDLSize', 'size'], inputData.size);\n    const comments = \"Station Code: \" + (inputData.stationCode || \"N/A\") + \"\\n\" + \"Local ID: \" + (inputData.bloomReportId || \"N/A\") + \"\\n\" + \"Location Description: \" + (inputData.locationDesc || \"\") + \"\\n\" + \"Notes: \" + (inputData.miscNotes || \"\");\n    setVal('TBComments', comments);\n  }\n} catch (error) {}\ncompletion(\"Autofill Complete\");\n    ")
